img {\r\n  max-width: 100%;\r\n  height: auto;\r\n  display: block;\r\n}\r\n\r\nul, ol {\r\n  list-style: none;\r\n}\r\n\r\n/* Containers */\r\n.container {\r\n  width: 100%;\r\n  max-width: var(--container-max);\r\n  margin-left: auto;\r\n  margin-right: auto;\r\n  padding-left: 1.5rem;\r\n  padding-right: 1.5rem;\r\n}\r\n\r\n.container-narrow {\r\n  width: 100%;\r\n  max-width: var(--container-narrow);\r\n  margin-left: auto;\r\n  margin-right: auto;\r\n  padding-left: 1.5rem;\r\n  padding-right: 1.5rem;\r\n}\r\n\r\n/* Section Wrapper */\r\n.section {\r\n  padding: 5.5rem 0;\r\n  position: relative;\r\n}\r\n\r\n.section-alt {\r\n  background-color: #FFFFFF;\r\n}\r\n\r\n.section-navy {\r\n  background-color: var(--color-primary);\r\n  color: #FFFFFF;\r\n}\r\n\r\n/* Section Headers */\r\n.section-header {\r\n  text-align: center;\r\n  max-width: 680px;\r\n  margin: 0 auto 3.5rem auto;\r\n}\r\n\r\n.section-header.text-left {\r\n  text-align: left;\r\n  margin-left: 0;\r\n}\r\n\r\n.section-tag {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  font-size: 0.8125rem;\r\n  font-weight: 700;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--color-secondary);\r\n  background-color: var(--color-secondary-tint);\r\n  padding: 0.35rem 0.9rem;\r\n  border-radius: var(--radius-full);\r\n  margin-bottom: 0.9rem;\r\n  border: 1px solid rgba(30, 77, 140, 0.15);\r\n}\r\n\r\n.section-tag-gold {\r\n  color: var(--color-accent-dark);\r\n  background-color: var(--color-accent-subtle);\r\n  border-color: rgba(214, 173, 96, 0.35);\r\n}\r\n\r\n.section-tag-navy {\r\n  color: var(--color-accent-light);\r\n  background-color: rgba(214, 173, 96, 0.12);\r\n  border-color: rgba(214, 173, 96, 0.25);\r\n}\r\n\r\n.section-title {\r\n  margin-bottom: 1rem;\r\n}\r\n\r\n.section-desc {\r\n  font-size: 1.1rem;\r\n  color: var(--color-text-muted);\r\n}\r\n\r\n.section-navy .section-title {\r\n  color: #FFFFFF;\r\n}\r\n\r\n.section-navy .section-d