/* --------------------------------------------------------------------------
   10. FAQ Accordion Section
   -------------------------------------------------------------------------- */
.faq-section {
  background-color: #FFFFFF;
}

.faq-accordion-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Staggered entrance animation for FAQ items */
@keyframes faqItemFadeIn {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.faq-accordion-list > .faq-item-card {
  animation: faqItemFadeIn 0.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.faq-accordion-list > .faq-item-card:nth-child(1) { animation-delay: 0.04s; }
.faq-accordion-list > .faq-item-card:nth-child(2) { animation-delay: 0.10s; }
.faq-accordion-list > .faq-item-card:nth-child(3) { animation-delay: 0.16s; }
.faq-accordion-list > .faq-item-card:nth-child(4) { animation-delay: 0.22s; }
.faq-accordion-list > .faq-item-card:nth-child(5) { animation-delay: 0.28s; }
.faq-accordion-list > .faq-item-card:nth-child(6) { animation-delay: 0.34s; }
.faq-accordion-list > .faq-item-card:nth-child(7) { animation-delay: 0.40s; }
.faq-accordion-list > .faq-item-card:nth-child(8) { animation-delay: 0.46s; }

.faq-item-card {
  position: relative;
  background-color: #FFFFFF;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.3s cubic-bezier(0.25, 1, 0.5, 1),
              border-color 0.3s ease,
              box-shadow 0.3s ease,
              background-color 0.3s ease;
}

/* Animated gold accent indicator on left */
.faq-item-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 4px;
  background: linear-gradient(180deg, var(--color-accent) 0%, var(--color-accent-dark) 100%);
  opacity: 0;
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.25s ease;
  z-index: 2;
}

.faq-item-card:hover {
  transform: translateY(-2px);
  border-color: var(--color-border-focus);
  box-shadow: 0 8px 20px rgba(16, 42, 67, 0.08);
}

.faq-item-card.is-open {
  border-color: var(--color-accent);
  background: linear-gradient(180deg, #FFFFFF 0%, var(--color-accent-subtle) 100%);
  box-shadow: 0 10px 24px -4px rgba(212, 168, 79, 0.16), 0 4px 10px -2px rgba(16, 42, 67, 0.05);
}

.faq-item-card.is-open::before {
  opacity: 1;
  transform: scaleY(1);
}

.faq-item-card.is-open:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px -4px rgba(212, 168, 79, 0.22), 0 6px 12px -2px rgba(16, 42, 67, 0.06);
}

.faq-question-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  text-align: left;
  background: none;
  border: none;
  cursor: pointer;
  position: relative;
  z-index: 1;
  transition: background-color 0.2s ease;
}

.faq-question-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: -2px;
}

.faq-question-text {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1.4;
  transition: color 0.25s ease;
}

.faq-question-btn:hover .faq-question-text {
  color: var(--color-secondary-light);
}

.faq-item-card.is-open .faq-question-text {
  color: var(--color-primary);
}

/* Smooth spring-easing rotating chevron */
.faq-chevron-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-color: transparent;
  color: var(--color-text-muted);
  transition: transform 0.38s cubic-bezier(0.34, 1.56, 0.64, 1),
              background-color 0.25s ease,
              color 0.25s ease;
  flex-shrink: 0;
}

.faq-question-btn:hover .faq-chevron-icon {
  background-color: rgba(16, 42, 67, 0.05);
  color: var(--color-primary);
}

.faq-chevron-icon.rotated {
  transform: rotate(180deg);
  background-color: rgba(212, 168, 79, 0.14);
  color: var(--color-accent-dark);
}

/* Buttery-smooth expand/collapse accordion via CSS Grid */
.faq-answer-collapse {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
  overflow: hidden;
}

.faq-answer-collapse.is-open {
  grid-template-rows: 1fr;
}

.faq-answer-inner {
  min-height: 0;
  overflow: hidden;
  padding: 0 1.5rem 0 1.5rem;
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.3s cubic-bezier(0.2, 0.8, 0.2, 1),
              transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
              padding 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.faq-answer-collapse.is-open .faq-answer-inner {
  padding: 0 1.5rem 1.35rem 1.5rem;
  opacity: 1;
  transform: translateY(0);
}

.faq-answer-inner p {
  font-size: 0.95rem;
  line-height: 1.68;
  color: var(--color-text-muted);
  margin: 0;
}

.faq-bottom-prompt {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.5rem;
  margin-top: 2.5rem;
  flex-wrap: wrap;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
