}

@media (max-width: 600px) {
  .faq-question-btn {
    padding: 1rem 1.1rem;
  }
  .faq-question-text {
    font-size: 0.95rem;
  }
  .faq-answer-inner {
    padding: 0 1.1rem 0 1.1rem;
  }
  .faq-answer-collapse.is-open .faq-answer-inner {
    padding: 0 1.1rem 1.1rem 1.1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .faq-accordion-list > .faq-item-card {
    animation: none !important;
  }
  .faq-item-card,
  .faq-item-card::before,
  .faq-chevron-icon,
  .faq-answer-collapse,
  .faq-answer-inner {
    transition: none !important;
  }
}

