  margin-bottom: 0.35rem;
}

.form-subtitle {
  font-size: 0.9rem;
}

.demo-mode-pill {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  background-color: var(--color-accent-subtle);
  border: 1px solid rgba(214, 173, 96, 0.4);
  padding: 0.75rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.825rem;
  color: var(--color-primary);
  margin-bottom: 1.5rem;
}

.demo-mode-pill a {
  color: var(--color-secondary);
  font-weight: 700;
  text-decoration: underline;
}

.demo-mode-pill svg {
  color: var(--color-accent-dark);
  flex-shrink: 0;
  margin-top: 0.15rem;
}

.submission-alert-banner {
  padding: 1.25rem;
  border-radius: var(--radius-md);
  margin-bottom: 1.5rem;
}

.alert-success,
.alert-demo {
  background-color: #F0FDF4;
  border: 1.5px solid #86EFAC;
  color: #14532D;
}

.btn-whatsapp {
  background-color: #25D366 !important;
  color: #FFFFFF !important;
  border: none !important;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: background-color 0.2s ease, transform 0.15s ease;
}

.btn-whatsapp:hover {
  background-color: #20BD5A !important;
  color: #FFFFFF !important;
  transform: translateY(-1px);
}

.whatsapp-preview-note {
  background-color: #F0FDF4 !important;
  border: 1px solid #BBF7D0 !important;
  color: #166534 !important;
}

.whatsapp-preview-note svg {
  color: #25D366 !important;
}

.alert-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.alert-icon {
  color: #16A34A;
}

.alert-text {
  font-size: 0.9rem;
  color: #166534;
  margin-bottom: 0.5rem;
}

.alert-action-prompt {
  font-size: 0.85rem;
  color: #14532D;
  margin-bottom: 0.85rem;
}

.alert-cta-buttons {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.form-row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-submit-row {
  margin-top: 1.5rem;
}

.submit-btn,
.submit-enquiry-btn {
  width: 100%;
  background: var(--color-accent) !important;
  color: var(--color-primary) !important;
  font-weight: 700 !important;
  border: none !important;
  box-shadow: 0 4px 14px rgba(212, 168, 79, 0.35) !important;
  transition: all var(--transition-fast);
}

.submit-btn:hover,
.submit-enquiry-btn:hover {
  background: var(--color-accent-dark) !important;
  color: var(--color-primary) !important;
  box-shadow: 0 6px 20px rgba(184, 141, 53, 0.45) !important;
  transform: translateY(-1px);
}

.spinner-icon {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@media (max-width: 992px) {
  .contact-layout-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .form-row-2 {
    grid-template-columns: 1fr;
  }
  .contact-info-card,
  .contact-form-card {
    padding: 1.5rem;
  }
}

@media (max-width: 480px) {
  .contact-info-card,
  .contact-form-card {
    padding: 1.25rem 0.85rem;
    border-radius: 10px;
  }
  .info-item {
    gap: 0.75rem;
  }
  .info-icon-wrapper {
    width: 38px;
    height: 38px;
  }
  .directions-link {
    font-size: 0.825rem;
  }
}

/* Modal details preview table */
.preview-details-table {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem;
  margin: 1.25rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.preview-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.9rem;
  border-bottom: 1px dashed var(--color-border);
  padding-bottom: 0.4rem;
}

.preview-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.preview-label {
  color: var(--color-text-muted);
  font-size: 0.825rem;
  font-weight: 600;
}

.preview-val {
  color: var(--color-text-dark);
}

.preview-note {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  font-size: 0.825rem;
  color: var(--color-text-muted);
}

.preview-note svg {
  color: var(--color-secondary);
  flex-shrink: 0;
  margin-top: 0.15rem;
}

/* Success Modal Styles */
.success-modal-dialog {
  max-width: 580px;
  border-top: 5px solid #22C55E;
}

.success-modal-header {
  border-bottom: 1px solid var(--color-border);
}

.success-badge-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.success-check-icon {
  color: #16A34A;
  flex-shrink: 0;
}

.whatsapp-modal-cta-box {
  background: #F0FDF4;
  border: 1.5px solid #86EFAC;
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin-top: 1.25rem;
  text-align: center;
}

.whatsapp-cta-text {
  font-size: 0.875rem;
  color: #14532D;
  margin-bottom: 0.85rem;
  font-weight: 500;
}

.btn-whatsapp-cta {
  width: 100%;
  justify-content: center;
  padding: 0.85rem 1.25rem;
  font-size: 1rem;
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.35);
}

.btn-whatsapp-cta:hover {
  box-shadow: 0 6px 20px rgba(37, 211, 102, 0.45);
}

.direct-connect-modal-box {
  background: #F0FDF4;
  border: 1.5px solid #86EFAC;
}

.modal-direct-actions-grid {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-top: 0.5rem;
}

.btn-modal-action {
  width: 100%;
  justify-content: center;
  font-weight: 600;
  padding: 0.75rem 1rem;
  gap: 0.5rem;
  text-decoration: none;
}

/* --------------------------------------------------------------------------
   12. Location & Map Section
   -------------------------------------------------------------------------- */
.location-section {
  background-color: #FFFFFF;
}

.location-grid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 2.5rem;
  align-items: stretch;
}

.location-details-box {
  background-color: var(--color-bg);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
}

.location-title {
  font-size: 1.5rem;
  margin-bottom: 0.6rem;
}

.location-address-text {
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 1.5rem;
  color: var(--color-text-dark);
}

.landmark-chips-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.75rem;
}

.landmark-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: #FFFFFF;
  border: 1px solid var(--color-border);
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius-md);
  font-size: 0.825rem;
  font-weight: 600;
  color: var(--color-primary);
}

.landmark-chip svg {
  color: var(--color-secondary);
}

.location-highlights {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  margin-bottom: 2rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--color-border);
}

.loc-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.loc-icon {
  color: var(--color-secondary);
  flex-shrink: 0;
  margin-top: 0.2rem;
}

.loc-item strong {
  font-size: 0.85rem;
  color: var(--color-primary);
  display: block;
}

.loc-item p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-top: 0.1rem;
}

.location-actions {
  margin-top: auto;
}

.location-map-wrapper {
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
  min-height: 400px;
}

.map-frame {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 400px;
}

.map-overlay-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  background-color: var(--color-primary);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 0.35rem;
  box-shadow: var(--shadow-md);
}

@media (max-width: 992px) {
  .location-grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   13. Footer
   -------------------------------------------------------------------------- */
.site-footer {
  background-color: var(--color-primary-dark);
  color: #CBD5E1;
  padding: 4.5rem 0 2rem 0;
  border-top: 1px solid rgba(214, 173, 96, 0.2);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 0.8fr 1fr 1.1fr;
  gap: 3rem;
  margin-bottom: 3.5rem;
}

.footer-logo-img {
  height: 60px;
  width: auto;
  max-width: 220px;
  margin-bottom: 1.25rem;
  object-fit: contain;
  filter: drop-shadow(0 2px 10px rgba(214, 173, 96, 0.25));
  transition: transform var(--transition-fast);
}

.footer-logo-img:hover {
  transform: scale(1.02);
}

.footer-about-text {
  font-size: 0.9rem;
  color: #94A3B8;
  line-height: 1.65;
  margin-bottom: 1.5rem;
}

.footer-badge-est {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.78rem;
  color: var(--color-accent-light);
  background: rgba(214, 173, 96, 0.1);
  padding: 0.35rem 0.8rem;
  border-radius: var(--radius-full);
  border: 1px solid rgba(214, 173, 96, 0.25);
}

.footer-heading {
  color: #FFFFFF;
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  letter-spacing: -0.01em;
}

.footer-links-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.footer-nav-btn {
  background: none;
  border: none;
  color: #94A3B8;
  font-size: 0.875rem;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  text-align: left;
  cursor: pointer;
  padding: 0.15rem 0;
  transition: color var(--transition-fast), transform var(--transition-fast);
}

.footer-nav-btn:hover {
  color: var(--color-accent-light);
  transform: translateX(3px);
}

.link-arrow {
  opacity: 0.6;
}

.footer-address {
  font-style: normal;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  font-size: 0.875rem;
  color: #94A3B8;
  line-height: 1.5;
}

.footer-contact-item .f-icon {
  color: var(--color-accent-light);
  flex-shrink: 0;
  margin-top: 0.2rem;
}

.footer-contact-item .f-link {
  color: #E2E8F0;
  font-weight: 600;
}

.footer-contact-item .f-link:hover {
  color: var(--color-accent-light);
  text-decoration: underline;
}

.footer-compliance-disclaimer {
  background: rgba(16, 35, 63, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  margin-bottom: 2.5rem;
}

.footer-compliance-disclaimer h5 {
  color: var(--color-accent-light);
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-compliance-disclaimer p {
  font-size: 0.8rem;
  color: #94A3B8;
  line-height: 1.6;
}

.footer-bottom-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-top: 1.75rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 0.825rem;
  color: #64748B;
  flex-wrap: wrap;
}

.legal-links {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.legal-btn {
  color: #94A3B8;
  font-size: 0.825rem;
  background: none;
  border: none;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.legal-btn:hover {
  color: var(--color-accent-light);
  text-decoration: underline;
}

.legal-sep {
  color: #475569;
}

@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 2.5rem;
  }
}

@media (max-width: 600px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom-bar {
    flex-direction: column;
    text-align: center;
    gap: 0.75rem;
  }
}
