rm 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),\r\n              padding 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);\r\n}\r\n\r\n.faq-answer-collapse.is-open .faq-answer-inner {\r\n  padding: 0 1.5rem 1.35rem 1.5rem;\r\n  opacity: 1;\r\n  transform: translateY(0);\r\n}\r\n\r\n.faq-answer-inner p {\r\n  font-size: 0.95rem;\r\n  line-height: 1.68;\r\n  color: var(--color-text-muted);\r\n  margin: 0;\r\n}\r\n\r\n.faq-bottom-prompt {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 1rem;\r\n  background-color: var(--color-bg);\r\n  border: 1px solid var(--color-border);\r\n  border-radius: var(--radius-md);\r\n  padding: 1.25rem 1.5rem;\r\n  margin-top: 2.5rem;\r\n  flex-wrap: wrap;\r\n  transition: border-color 0.25s ease, box-shadow 0.25s ease;\r\n}\r\n\r\n.faq-bottom-prompt:hover {\r\n  border-color: var(--color-border-focus);\r\n  box-shadow: 0 4px 12px rgba(16, 42, 67, 0.05);\r\n}\r\n\r\n.prompt-icon {\r\n  color: var(--color-secondary);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.prompt-text {\r\n  display: flex;\r\n  flex-direction: column;\r\n  flex: 1;\r\n}\r\n\r\n.prompt-text strong {\r\n  color: var(--color-primary);\r\n  font-size: 0.95rem;\r\n}\r\n\r\n.prompt-text span {\r\n  color: var(--color-text-muted);\r\n  font-size: 0.85rem;\r\n}\r\n\r\n@media (max-width: 600px) {\r\n  .faq-question-btn {\r\n    padding: 1rem 1.1rem;\r\n  }\r\n  .faq-question-text {\r\n    font-size: 0.95rem;\r\n  }\r\n  .faq-answer-inner {\r\n    padding: 0 1.1rem 0 1.1rem;\r\n  }\r\n  .faq-answer-collapse.is-open .faq-answer-inner {\r\n    padding: 0 1.1rem 1.1rem 1.1rem;\r\n  }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .faq-accordion-list > .faq-item-card {\r\n    animation: none !important;\r\n  }\r\n  .faq-item-card,\r\n  .faq-item-card::before,\r\n  .faq-chevron-icon,\r\n  .faq-answer-collapse,\r\n  .faq-answer-inner {\r\n    transition: none !important;\r\n  }\r\n}\r\n\r\n/* -----------------------------------------------------------------